<?php
namespace App\Controllers\Admin;
use App\Controllers\BaseController; use App\Models\ProductCategoryModel; use App\Models\ProductImageModel; use App\Models\ProductModel; use App\Models\ProductPackageItemModel; use App\Models\ProductVariantModel; use App\Services\ActivityLogService; use App\Services\ImageUploadService; use App\Services\ProductService;
class ProductController extends BaseController
{
    public function index(){ $m=(new ProductModel())->withCategory();$q=trim((string)$this->request->getGet('q'));$category=(int)$this->request->getGet('category_id');$status=(string)$this->request->getGet('status');$type=(string)$this->request->getGet('type');$featured=(string)$this->request->getGet('featured');$stock=(string)$this->request->getGet('stock');if($q)$m->groupStart()->like('products.name',$q)->orLike('products.product_code',$q)->orLike('products.sku',$q)->groupEnd();if($category)$m->where('products.category_id',$category);if(in_array($status,['draft','active','inactive','out_of_stock'],true))$m->where('products.status',$status);if(in_array($type,['simple','variant'],true))$m->where('products.stock_type',$type);if($featured!=='')$m->where('products.featured',$featured==='1');if($stock==='low')$m->where('products.stock_quantity >',0)->where('products.stock_quantity <= products.low_stock_threshold',null,false);if($stock==='out')$m->where('products.stock_quantity <=',0);return view('admin/products/index',['title'=>'Products','products'=>$m->orderBy('products.id','DESC')->paginate(20),'pager'=>$m->pager,'categories'=>(new ProductCategoryModel())->orderBy('name')->findAll(),'filters'=>compact('q','category','status','type','featured','stock')]);}
    public function create(){return $this->form(null);}
    public function edit(int $id){$product=(new ProductModel())->find($id);if(!$product)throw \CodeIgniter\Exceptions\PageNotFoundException::forPageNotFound();return $this->form($product);}
    private function form(?array $product){$id=(int)($product['id']??0);return view('admin/products/form',['title'=>$id?'Edit Product':'Create Product','product'=>$product,'categories'=>(new ProductCategoryModel())->where('status','active')->orderBy('name')->findAll(),'variants'=>$id?(new ProductVariantModel())->where('product_id',$id)->orderBy('sort_order')->findAll():[],'images'=>$id?(new ProductImageModel())->where('product_id',$id)->orderBy('sort_order')->findAll():[]]);}
    public function store(){return $this->save(null);} public function update(int $id){return $this->save($id);}
    private function save(?int $id){$rules=['name'=>'required|min_length[2]|max_length[190]','category_id'=>'permit_empty|is_natural_no_zero|is_not_unique[product_categories.id]','regular_price'=>'required|decimal|greater_than_equal_to[0]','sale_price'=>'permit_empty|decimal|greater_than_equal_to[0]','purchase_cost'=>'permit_empty|decimal|greater_than_equal_to[0]','stock_type'=>'required|in_list[simple,variant]','stock_quantity'=>'required|integer|greater_than_equal_to[0]','low_stock_threshold'=>'required|integer|greater_than_equal_to[0]','status'=>'required|in_list[draft,active,inactive,out_of_stock]'];if(!$this->validate($rules))return redirect()->back()->withInput()->with('errors',$this->validator->getErrors());$regular=(float)$this->request->getPost('regular_price');$sale=$this->request->getPost('sale_price');if($sale!==''&&(float)$sale>$regular)return redirect()->back()->withInput()->with('danger','Sale price cannot exceed regular price.');$sku=trim((string)$this->request->getPost('sku'))?:null;if($sku){$dup=(new ProductModel())->where('sku',$sku);if($id)$dup->where('id !=',$id);if($dup->first()||(new ProductVariantModel())->where('sku',$sku)->first())return redirect()->back()->withInput()->with('danger','This SKU is already in use.');}$data=['category_id'=>(int)$this->request->getPost('category_id')?:null,'name'=>trim((string)$this->request->getPost('name')),'slug'=>trim((string)$this->request->getPost('slug')),'short_description'=>trim((string)$this->request->getPost('short_description'))?:null,'description'=>trim((string)$this->request->getPost('description'))?:null,'regular_price'=>$regular,'sale_price'=>$sale===''?null:(float)$sale,'purchase_cost'=>$this->request->getPost('purchase_cost')===''?null:(float)$this->request->getPost('purchase_cost'),'sku'=>$sku,'stock_type'=>$this->request->getPost('stock_type'),'stock_quantity'=>(int)$this->request->getPost('stock_quantity'),'low_stock_threshold'=>(int)$this->request->getPost('low_stock_threshold'),'manage_stock'=>(bool)$this->request->getPost('manage_stock'),'allow_backorder'=>(bool)$this->request->getPost('allow_backorder'),'weight'=>$this->request->getPost('weight')===''?null:(float)$this->request->getPost('weight'),'weight_unit'=>$this->request->getPost('weight_unit')?:'kg','unit'=>trim((string)$this->request->getPost('unit'))?:null,'featured'=>(bool)$this->request->getPost('featured'),'status'=>$this->request->getPost('status'),'seo_title'=>trim((string)$this->request->getPost('seo_title'))?:null,'seo_description'=>trim((string)$this->request->getPost('seo_description'))?:null,'seo_keywords'=>trim((string)$this->request->getPost('seo_keywords'))?:null,'sort_order'=>(int)$this->request->getPost('sort_order')];try{$id=(new ProductService())->save($id,$data,$this->request->getPost('variants')??[],$this->request->getFiles()['images']??[]);}catch(\Throwable $e){return redirect()->back()->withInput()->with('danger',$e->getMessage());}(new ActivityLogService())->log($this->request->getPost('_method')==='PUT'?'product.update':'product.create','products','Product saved.',['product_id'=>$id]);return redirect()->to(url_to('admin.products.show',$id))->with('success','Product saved successfully.');}
    public function show(int $id){$p=(new ProductModel())->withCategory()->where('products.id',$id)->first();if(!$p)throw \CodeIgniter\Exceptions\PageNotFoundException::forPageNotFound();return view('admin/products/show',['title'=>'Product Preview','product'=>$p,'variants'=>(new ProductVariantModel())->where('product_id',$id)->orderBy('sort_order')->findAll(),'images'=>(new ProductImageModel())->where('product_id',$id)->orderBy('sort_order')->findAll(),'movements'=>db_connect()->table('inventory_movements')->where('product_id',$id)->orderBy('id','DESC')->limit(10)->get()->getResultArray()]);}
    public function delete(int $id){if((new ProductPackageItemModel())->where('product_id',$id)->countAllResults()>0)return redirect()->back()->with('danger','This product is used in a package and cannot be deleted.');(new ProductVariantModel())->where('product_id',$id)->delete();(new ProductModel())->delete($id);(new ActivityLogService())->log('product.delete','products','Product deleted.',['product_id'=>$id]);return redirect()->to(url_to('admin.products'))->with('success','Product deleted successfully.');}
    public function imageDelete(int $id){$m=new ProductImageModel();$image=$m->find($id);if(!$image)throw \CodeIgniter\Exceptions\PageNotFoundException::forPageNotFound();(new ImageUploadService())->delete($image['image_path']);$m->delete($id);$first=$m->where('product_id',$image['product_id'])->orderBy('sort_order')->first();(new ProductModel())->update($image['product_id'],['main_image'=>$first['image_path']??null]);return redirect()->back()->with('success','Image deleted.');}
    public function imagesUpdate(int $id){$rows=(array)$this->request->getPost('image_meta');$model=new ProductImageModel();$primary=(int)$this->request->getPost('primary_image');$model->where('product_id',$id)->set(['is_primary'=>0])->update();foreach($rows as $imageId=>$row){$image=$model->where(['id'=>(int)$imageId,'product_id'=>$id])->first();if(!$image)continue;$model->update($image['id'],['alt_text'=>trim((string)($row['alt_text']??''))?:null,'sort_order'=>(int)($row['sort_order']??0),'is_primary'=>$image['id']===$primary]);}if(!$primary){$first=$model->where('product_id',$id)->orderBy('sort_order')->first();$primary=(int)($first['id']??0);if($primary)$model->update($primary,['is_primary'=>1]);}$selected=$primary?$model->find($primary):null;(new ProductModel())->update($id,['main_image'=>$selected['image_path']??null]);return redirect()->back()->with('success','Image details updated.');}
    public function duplicate(int $id){$p=(new ProductModel())->find($id);if(!$p)throw \CodeIgniter\Exceptions\PageNotFoundException::forPageNotFound();unset($p['id'],$p['product_code'],$p['created_at'],$p['updated_at'],$p['deleted_at']);$p['name'].=' - Copy';$p['slug']=$p['name'];$p['sku']=null;$p['status']='draft';$variants=(new ProductVariantModel())->where('product_id',$id)->findAll();foreach($variants as &$v){unset($v['id'],$v['product_id'],$v['created_at'],$v['updated_at'],$v['deleted_at']);$v['sku']=null;}$new=(new ProductService())->save(null,$p,$variants,[]);(new ActivityLogService())->log('product.duplicate','products','Product duplicated.',['source_id'=>$id,'product_id'=>$new]);return redirect()->to(url_to('admin.products.edit',$new))->with('success','Product duplicated as a draft.');}
    public function bulk(){ $ids=array_map('intval',(array)$this->request->getPost('ids'));$action=(string)$this->request->getPost('action');if(!$ids)return redirect()->back()->with('danger','Select at least one product.');$m=new ProductModel();match($action){'activate'=>$m->whereIn('id',$ids)->set(['status'=>'active'])->update(),'deactivate'=>$m->whereIn('id',$ids)->set(['status'=>'inactive'])->update(),'feature'=>$m->whereIn('id',$ids)->set(['featured'=>1])->update(),'unfeature'=>$m->whereIn('id',$ids)->set(['featured'=>0])->update(),'delete'=>$m->whereIn('id',$ids)->delete(),default=>null};return redirect()->back()->with('success','Bulk action completed.');}
}
